from pathlib import Path

root = Path('/app/app')
(root / 'db.py').write_text('''import os
import sqlite3
from pathlib import Path

DATABASE_URL = os.getenv("DATABASE_URL", "").strip()
DB_PATH = os.getenv("DATABASE_PATH", "./data/app.db")
IS_POSTGRES = DATABASE_URL.startswith(("postgres://", "postgresql://"))

def connect():
    if IS_POSTGRES:
        import psycopg
        from psycopg.rows import dict_row
        url = DATABASE_URL.replace("postgres://", "postgresql://", 1)
        return psycopg.connect(url, row_factory=dict_row, connect_timeout=10)
    Path(DB_PATH).parent.mkdir(parents=True, exist_ok=True)
    c = sqlite3.connect(DB_PATH, timeout=10)
    c.row_factory = sqlite3.Row
    c.execute("PRAGMA foreign_keys=ON")
    return c

def execute(c, sql, params=()):
    if IS_POSTGRES:
        sql = sql.replace("?", "%s")
    return c.execute(sql, params)

def init_db():
    statements = [
        """CREATE TABLE IF NOT EXISTS submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, company TEXT NOT NULL, inn TEXT NOT NULL, industry TEXT NOT NULL, size TEXT NOT NULL, municipality TEXT NOT NULL, last_name TEXT NOT NULL, first_name TEXT NOT NULL, middle_name TEXT, position TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, answers_json TEXT NOT NULL, result_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'result_calculated')""",
        "CREATE INDEX IF NOT EXISTS idx_inn ON submissions(inn)",
        "CREATE INDEX IF NOT EXISTS idx_created ON submissions(created_at)",
    ]
    if IS_POSTGRES:
        statements[0] = statements[0].replace("id INTEGER PRIMARY KEY AUTOINCREMENT", "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY")
    with connect() as c:
        for statement in statements:
            c.execute(statement)
''', encoding='utf-8')

main = root / 'main.py'
s = main.read_text(encoding='utf-8')
s = s.replace('from .db import init_db,connect', 'from .db import init_db,connect,execute,IS_POSTGRES')
s = s.replace('c.execute(', 'execute(c, ')
old = """cur=execute(c, '''INSERT INTO submissions(company,inn,industry,size,municipality,last_name,first_name,middle_name,position,phone,email,answers_json,result_json,status)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',(company.strip(),inn.strip(),industry.strip(),size.strip(),municipality.strip(),last_name.strip(),first_name.strip(),middle_name.strip(),position.strip(),phone.strip(),email.strip(),json.dumps(answers,ensure_ascii=False),json.dumps(result,ensure_ascii=False),'result_calculated'))
        sid=cur.lastrowid"""
new = """insert_sql='''INSERT INTO submissions(company,inn,industry,size,municipality,last_name,first_name,middle_name,position,phone,email,answers_json,result_json,status)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)'''
        params=(company.strip(),inn.strip(),industry.strip(),size.strip(),municipality.strip(),last_name.strip(),first_name.strip(),middle_name.strip(),position.strip(),phone.strip(),email.strip(),json.dumps(answers,ensure_ascii=False),json.dumps(result,ensure_ascii=False),'result_calculated')
        if IS_POSTGRES:
            sid=execute(c, insert_sql + ' RETURNING id', params).fetchone()['id']
        else:
            sid=execute(c, insert_sql, params).lastrowid"""
if old in s:
    s = s.replace(old, new)
elif not ("insert_sql='''INSERT INTO submissions" in s and 'IS_POSTGRES' in s):
    raise SystemExit('Postgres patch failed: INSERT block not found')  # already patched or unexpected source
main.write_text(s, encoding='utf-8')
req = Path('/app/requirements.txt')
requirements = req.read_text(encoding='utf-8')
if 'psycopg[binary]' not in requirements:
    req.write_text(requirements.rstrip() + '\npsycopg[binary]>=3.2,<4\n', encoding='utf-8')


